import { MakeLogicType, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import { router } from 'kea-router'

import { projectLogic } from 'scenes/projectLogic'
import { urls } from 'scenes/urls'

import { hogFlowsList } from '../generated/api'
import type { HogFlowMinimalApi } from '../generated/api.schemas'

export type ApiSendsResolution = 'loading' | 'redirecting' | 'empty' | 'error'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface apiSendsSceneLogicValues {
    currentProjectId: number | null // projectLogic
    apiSendsFlow: HogFlowMinimalApi | null
    apiSendsFlowLoading: boolean
    resolution: ApiSendsResolution
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface apiSendsSceneLogicActions {
    loadApiSendsFlow: () => any
    loadApiSendsFlowFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadApiSendsFlowSuccess: (
        apiSendsFlow: HogFlowMinimalApi | null,
        payload?: any
    ) => {
        apiSendsFlow: HogFlowMinimalApi | null
        payload?: any
    }
}

export type apiSendsSceneLogicType = MakeLogicType<apiSendsSceneLogicValues, apiSendsSceneLogicActions>

export const apiSendsSceneLogic = kea<apiSendsSceneLogicType>([
    path(['products', 'workflows', 'frontend', 'ApiSends', 'apiSendsSceneLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        apiSendsFlow: [
            null as HogFlowMinimalApi | null,
            {
                loadApiSendsFlow: async (): Promise<HogFlowMinimalApi | null> => {
                    const { results } = await hogFlowsList(String(values.currentProjectId), {
                        type: 'api_send',
                        limit: 1,
                    })
                    return results[0] ?? null
                },
            },
        ],
    })),
    reducers({
        resolution: [
            'loading' as ApiSendsResolution,
            {
                loadApiSendsFlow: () => 'loading',
                loadApiSendsFlowSuccess: (_, { apiSendsFlow }) => (apiSendsFlow ? 'redirecting' : 'empty'),
                loadApiSendsFlowFailure: () => 'error',
            },
        ],
    }),
    listeners({
        loadApiSendsFlowSuccess: ({ apiSendsFlow }) => {
            if (apiSendsFlow) {
                router.actions.replace(urls.workflow(apiSendsFlow.id, 'invocations'))
            }
        },
    }),
    afterMount(({ actions }) => {
        actions.loadApiSendsFlow()
    }),
])
